const EXCLUDE_IDS = new Set(['99811284']); // Agent Haxe bot - never an onboardee
const FULL_ROLES = new Set(['owner','admin','member']); // exclude guest + limited_member
const ACTIVE_DAYS = 30;
const now = Date.now();

const teams = ($('Get Team').first().json.teams) || [];
let state = $('Get Onboarding State').first().json.state || {};
if (typeof state === 'string') { try { state = JSON.parse(state); } catch (e) { state = {}; } }
const mcp = new Set((state.mcp_ids || []).map(String));
const rest = new Set((state.rest_ids || []).map(String));

const missing = [];
const seen = new Set();
for (const t of teams) {
  for (const m of (t.members || [])) {
    const u = m.user || {};
    const id = String(u.id);
    if (!id || id === 'undefined' || seen.has(id)) continue;
    seen.add(id);
    if (EXCLUDE_IDS.has(id)) continue;
    if (!FULL_ROLES.has(u.role_key)) continue;
    const la = u.last_active ? Number(u.last_active) : null;
    if (!la || (now - la) > ACTIVE_DAYS * 86400000) continue;
    const hasMcp = mcp.has(id);
    const hasRest = rest.has(id);
    if (hasMcp && hasRest) continue;
    const lacks = [];
    if (!hasMcp) lacks.push('MCP (discovery)');
    if (!hasRest) lacks.push('REST (extraction)');
    missing.push({ id, username: u.username || '(?)', email: u.email || '(?)', role: u.role_key, days_since: Math.round((now - la) / 86400000), missing: lacks });
  }
}
missing.sort((a, b) => String(a.username).localeCompare(String(b.username)));

const lines = missing.map(x => `- ${x.username} (${x.email}, ${x.role}): brak ${x.missing.join(' + ')}`);
const details = missing.length
  ? `Aktywni (ostatnia aktywnosc <=${ACTIVE_DAYS} dni) pelni czlonkowie ClickUp bez kompletu tokenow ADR-054 (${missing.length}):\n` + lines.join('\n') + `\n\nDodaj brakujace: MCP (discovery) -> node scripts/onboard-clickup-mcp-user.mjs; REST (extraction) -> node scripts/onboard-clickup-rest-token.mjs. Po onboardingu WARN zniknie przy nastepnym przebiegu.`
  : `OK - wszyscy aktywni pelni czlonkowie ClickUp maja oba tokeny.`;

return [{ json: { count: missing.length, details, missing } }];
